import re, zlib, zipfile, sys, os

def inflate_pdf_streams(data):
    out = []
    for m in re.finditer(rb'stream\r?\n', data):
        start = m.end()
        end = data.find(b'endstream', start)
        if end < 0:
            continue
        raw = data[start:end]
        for tail in (0, 1, 2):
            try:
                out.append(zlib.decompress(raw[:len(raw)-tail] if tail else raw))
                break
            except Exception:
                continue
        else:
            out.append(raw)
    return out

def hex_to_text(chunk):
    # chunk is bytes of hex; decode UTF-16BE per 4-hex-digit code unit
    try:
        s = chunk.decode('ascii', 'ignore')
        s = re.sub(r'[^0-9A-Fa-f]', '', s)
        if len(s) % 4:
            s = s[:len(s)//4*4]
        b = bytes.fromhex(s)
        return b.decode('utf-16-be', 'ignore')
    except Exception:
        return ''

def pdf_text(path):
    data = open(path, 'rb').read()
    pieces = []
    for st in inflate_pdf_streams(data):
        # capture TJ / Tj hex strings in order with newline on TD/Td/T*
        txt_parts = []
        for tm in re.finditer(rb'(?:\[(.*?)\]\s*TJ)|(?:<([0-9A-Fa-f]+)>\s*Tj)|(T\*)|(?:[-\d.]+\s+[-\d.]+\s+Td)|(ET)', st, re.S):
            if tm.group(1) is not None:
                inner = tm.group(1)
                seg = []
                for hm in re.finditer(rb'<([0-9A-Fa-f]+)>', inner):
                    seg.append(hex_to_text(hm.group(1)))
                txt_parts.append(''.join(seg))
            elif tm.group(2) is not None:
                txt_parts.append(hex_to_text(tm.group(2)))
            elif tm.group(3) is not None or tm.group(5) is not None:
                txt_parts.append('\n')
        t = ''.join(txt_parts)
        if t.strip():
            pieces.append(t)
    return '\n'.join(pieces)

def docx_text(path):
    z = zipfile.ZipFile(path)
    xml = z.read('word/document.xml').decode('utf-8', 'ignore')
    xml = re.sub(r'</w:p>', '\n', xml)
    xml = re.sub(r'</w:tc>', ' | ', xml)
    xml = re.sub(r'</w:tr>', '\n', xml)
    xml = re.sub(r'<w:tab/>', '\t', xml)
    xml = re.sub(r'<w:br/>', '\n', xml)
    txt = re.sub(r'<[^>]+>', '', xml)
    txt = txt.replace('&amp;', '&').replace('&lt;', '<').replace('&gt;', '>').replace('&quot;', '"').replace('&apos;', "'")
    lines = [l.strip() for l in txt.split('\n')]
    return '\n'.join([l for l in lines if l])

def xlsx_text(path):
    z = zipfile.ZipFile(path)
    shared = []
    if 'xl/sharedStrings.xml' in z.namelist():
        s = z.read('xl/sharedStrings.xml').decode('utf-8', 'ignore')
        for si in re.findall(r'<si>(.*?)</si>', s, re.S):
            shared.append(''.join(re.findall(r'<t[^>]*>(.*?)</t>', si, re.S)))
    out = []
    wb = z.read('xl/workbook.xml').decode('utf-8', 'ignore')
    names = re.findall(r'<sheet[^>]*name="([^"]+)"', wb)
    sheets = sorted([n for n in z.namelist() if re.match(r'xl/worksheets/sheet\d+\.xml$', n)])
    for idx, sh in enumerate(sheets):
        out.append('=== Sheet: %s ===' % (names[idx] if idx < len(names) else sh))
        s = z.read(sh).decode('utf-8', 'ignore')
        for row in re.findall(r'<row[^>]*>(.*?)</row>', s, re.S):
            cells = []
            for c in re.findall(r'<c[^>]*?(?:/>|>.*?</c>)', row, re.S):
                t = re.search(r't="([^"]+)"', c)
                v = re.search(r'<v>(.*?)</v>', c, re.S)
                isx = re.search(r'<is>(.*?)</is>', c, re.S)
                if isx:
                    cells.append(''.join(re.findall(r'<t[^>]*>(.*?)</t>', isx.group(1), re.S)))
                elif v:
                    val = v.group(1)
                    if t and t.group(1) == 's':
                        try:
                            val = shared[int(val)]
                        except Exception:
                            pass
                    cells.append(val)
                else:
                    cells.append('')
            line = ' | '.join(cells).strip()
            if line.replace('|', '').strip():
                out.append(line)
    return '\n'.join(out)

for p in sys.argv[1:]:
    ext = os.path.splitext(p)[1].lower()
    print('\n\n########', os.path.basename(p), '########')
    try:
        if ext == '.pdf':
            print(pdf_text(p))
        elif ext == '.docx':
            print(docx_text(p))
        elif ext == '.xlsx':
            print(xlsx_text(p))
    except Exception as e:
        print('ERR', type(e).__name__, e)

